args.sql:
-- Verify dwelling class distribution
SELECT LOWER(TRIM(p.dwelling_specs->>'Dwelling_Class')) as dc, COUNT(*) 
FROM properties p GROUP BY dc ORDER BY COUNT(*) DESC;

-- Check cable status values containing 'avail' or 'yes'
SELECT DISTINCT LOWER(a.cablestatus) as cs FROM amenities a 
WHERE LOWER(a.cablestatus) LIKE '%avail%' OR LOWER(a.cablestatus) LIKE '%yes%';

-- Maybe quality residence is just about dwelling_specs, not cable status
SELECT COUNT(*) FROM properties 
WHERE LOWER(TRIM(dwelling_specs->>'Dwelling_Class')) IN ('brickwork house', 'apartment');

-- Count properties with qualifying dwelling classes
SELECT COUNT(*) FROM properties 
WHERE LOWER(TRIM(dwelling_specs->>'Dwelling_Class')) IN ('brickwork house', 'apartment');

